import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const SOURCE_PATH = '/root/data/object.js';
const OUTPUT_PATH = '/root/output/object.obj';

async function main() {
  const moduleUrl = pathToFileURL(SOURCE_PATH).href;
  const module = await import(moduleUrl);
  if (typeof module.createScene !== 'function') {
    throw new Error(`Expected createScene() export in ${SOURCE_PATH}`);
  }

  const root = module.createScene();
  if (!root || !root.isObject3D) {
    throw new Error('createScene() did not return a THREE.Object3D');
  }

  root.updateMatrixWorld(true);

  const geometries = [];
  const instanceMatrix = new THREE.Matrix4();
  const combinedMatrix = new THREE.Matrix4();

  root.traverse((obj) => {
    if (obj.isInstancedMesh) {
      const baseGeom = obj.geometry;
      for (let i = 0; i < obj.count; i += 1) {
        obj.getMatrixAt(i, instanceMatrix);
        combinedMatrix.multiplyMatrices(obj.matrixWorld, instanceMatrix);
        const geom = baseGeom.clone();
        geom.applyMatrix4(combinedMatrix);
        geometries.push(geom);
      }
      return;
    }

    if (obj.isMesh) {
      const geom = obj.geometry.clone();
      geom.applyMatrix4(obj.matrixWorld);
      geometries.push(geom);
    }
  });

  if (geometries.length === 0) {
    throw new Error('No geometry found to export.');
  }

  const merged = mergeGeometries(geometries, false);
  if (!merged) {
    throw new Error('Failed to merge geometries.');
  }

  // Convert from Three.js Y-up to Blender Z-up by rotating -90 degrees around X.
  merged.applyMatrix4(new THREE.Matrix4().makeRotationX(-Math.PI / 2));

  const exporter = new OBJExporter();
  const objData = exporter.parse(new THREE.Mesh(merged));

  fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, objData, 'utf8');

  console.log(`OBJ written to ${OUTPUT_PATH}`);
}

